mutations.before:
...(timeline !== undefined
  ? {
      timeline: {
        transition: timeline.transition,
        keyBeat: timeline.keyBeat,
        beats: timeline.beats.map((beat) => ({
          text: beat.text,
          weight: beat.weight,
          ...(beat.background !== undefined ? { background: beat.background } : {}),
        })),
      },
    }
  : {}),

beats: timeline.beats.map((beat) => ({
  text: beat.text,
  weight: beat.weight,
  ...(beat.background !== undefined ? { background: beat.background } : {}),
})),

mutations.after:
beats: timeline.beats.map((beat) => ({
  text: beat.text,
  ...(beat.background !== undefined ? { background: beat.background } : {}),
})),
